fn find_min(a: &[i32], lo: usize) -> usize {
    // Start by assuming the minimal element is at index `lo`
    let mut min_idx = lo;

    // Iterate through the subarray from `lo + 1` to the end
    for i in (lo + 1)..a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }

    min_idx
}

